# Try: minority element in each row (the one that appears fewer times)
grid = [
    [5, 5, 5],
    [5, 5, 5],
    [8, 8, 8],
    [7, 7, 5],
    [5, 4, 5]
]

def find_minority(row):
    counts = {}
    for val in row:
        counts[val] = counts.get(val, 0) + 1
    # Return the value with minimum count
    return min(counts, key=counts.get)

output = [find_minority(row) for row in grid]
print("Minority per row:", output)

