# Try: for each row, fill with majority color
def majority_fill(row):
    if not row:
        return row
    counts = {}
    for val in row:
        counts[val] = counts.get(val, 0) + 1
    most_common = max(counts, key=counts.get)
    return [most_common] * len(row)

output = majority_fill(grid)
